@import url('');

:root {
    --primary: #0A61F7; 
    --secondary: #39FF14; 
    --accent: #0A61F7;
    --border-glow: rgba(10, 97, 247, 0.5); 
    --primary-rgb: 10, 97, 247; 
    --secondary-rgb: 57, 255, 20;
    --bg: #000000; 
    --surface: rgba(10, 10, 10, 0.7); 
    --glass: rgba(255, 255, 255, 0.02);
    --glass-strong: rgba(255, 255, 255, 0.05); 
    --border: rgba(255, 255, 255, 0.08);
    --text: #f0f0f0; 
    --text-muted: #94a3b8; 
    --radius-lg: 24px; 
    --radius-md: 16px; 
    --radius-sm: 12px;
    --shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
    --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1); 
    --transition-color-slow: 15s ease-in-out;
}
* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html { height: 100%; height: -webkit-fill-available; scroll-behavior: smooth; }
body {
    font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text);
    min-height: 100vh; min-height: -webkit-fill-available; overflow: hidden;
    -webkit-font-smoothing: antialiased; font-size: 15px;
}
.aurora-background { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: -1; overflow: hidden; will-change: transform; }
.aurora { position: absolute; border-radius: 50%; mix-blend-mode: screen; filter: blur(120px); opacity: 0; transition: background-color var(--transition-color-slow), opacity 8s ease-in-out; animation: pulse 30s ease-in-out infinite alternate; will-change: transform, opacity; }
.aurora.visible { opacity: 0.3; }
.aurora.one { width: 80vmax; height: 80vmax; animation-name: move-one, pulse; animation-duration: 1200s, 35s; animation-timing-function: linear, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
.aurora.two { width: 70vmax; height: 70vmax; animation-name: move-two, pulse; animation-duration: 1050s, 40s; animation-timing-function: linear, ease-in-out; animation-iteration-count: infinite, infinite; animation-direction: alternate, alternate; }
@keyframes move-one { from { transform: translate(-20vw, -20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
@keyframes move-two { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(-10vw, 60vh) scale(1.3); } }
@keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
.container { display: flex; min-height: 100vh; min-height: -webkit-fill-available; position: relative; }

.welcome-title, .modal-title, .header-title { background: linear-gradient(135deg, var(--primary), var(--secondary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
