.completion-stats h3 { color: var(--primary); font-size: 1rem; margin-bottom: 12px; display: flex; align-items: center; gap: 8px; }
.stats-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin-bottom: 16px; }
.stat-item { text-align: center; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; }
.stat-number { display: block; font-size: 1.5rem; font-weight: 700; color: var(--primary); margin-bottom: 4px; }
.stat-label { font-size: 0.7rem; color: var(--text-muted); font-weight: 500; }
.document-preview { background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 10px; display: flex; align-items: center; gap: 10px; cursor: pointer; transition: all 0.2s ease; }
.document-preview:hover { background: var(--glass-strong); border-color: var(--primary); transform: translateY(-2px); }
