import os
import json
import asyncio
from typing import List, Optional, Dict, Any

import uvicorn
import requests
from fastapi import FastAPI, Request, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse, JSONResponse, FileResponse, PlainTextResponse

from cerebras.cloud.sdk import Cerebras

CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY")
EXA_API_KEY = os.environ.get("EXA_API_KEY")

if not CEREBRAS_API_KEY:
    raise RuntimeError("Hiányzik a CEREBRAS_API_KEY környezeti változó.")
if not EXA_API_KEY:
    raise RuntimeError("Hiányzik az EXA_API_KEY környezeti változó.")

client = Cerebras(api_key=CEREBRAS_API_KEY)

app = FastAPI(title="Cerebras + Exa Chat", version="1.0.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/health")
def health():
    return {"status": "ok"}


@app.get("/")
def root():
    # Kiszolgálja az index.html-t a gyökérből
    return FileResponse("index.html", media_type="text/html")


def exa_search(query: str, num_results: int = 100, search_type: str = "fast") -> Dict[str, Any]:
    """
    Hívja az Exa /search API-t 'fast' típussal és max 100 találattal.
    """
    url = ""
    headers = {
        "Content-Type": "application/json",
        "x-api-key": EXA_API_KEY,
    }
    payload = {
        "query": query,
        "type": search_type,
        "num_results": num_results
    }
    r = requests.post(url, headers=headers, json=payload, timeout=60)
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail=f"Exa search error: {r.text}")
    return r.json()


def exa_get_contents(urls: List[str], livecrawl: str = "preferred", return_text: bool = True) -> Dict[str, Any]:
    """
    Hívja az Exa /contents API-t a teljes oldal szövegéért, igény szerint livecrawl-lal.
    """
    url = ""
    headers = {
        "Content-Type": "application/json",
        "x-api-key": EXA_API_KEY,
    }
    payload: Dict[str, Any] = {
        "urls": urls,
        "livecrawl": livecrawl
    }
    if return_text:
        payload["text"] = True
    r = requests.post(url, headers=headers, json=payload, timeout=120)
    if r.status_code != 200:
        raise HTTPException(status_code=502, detail=f"Exa contents error: {r.text}")
    return r.json()


@app.post("/api/exa/search")
def api_exa_search(body: Dict[str, Any]):
    """
    Keresés + opcionális tartalomkinyerés (always 100 results).
    body: { "query": str, "with_contents": bool, "max_pages": int }
    """
    query = body.get("query", "").strip()
    if not query:
        raise HTTPException(status_code=400, detail="Hiányzó 'query'.")

    with_contents = bool(body.get("with_contents", True))
    max_pages = int(body.get("max_pages", 8))  # tartalomkinyeréshez
    search = exa_search(query=query, num_results=100, search_type="fast")

    results = search.get("results", []) or search.get("data", []) or []
    urls = [r.get("url") for r in results if r.get("url")]
    urls = urls[:max_pages] if with_contents else urls

    contents = None
    if with_contents and urls:
        contents = exa_get_contents(urls=urls, livecrawl="preferred", return_text=True)

    return {"search": search, "contents": contents}


@app.post("/api/exa/research")
def api_exa_research(body: Dict[str, Any]):
    """
    Létrehoz egy Exa Research feladatot (asynchronous pipeline), visszaadja a researchId-t.
    body: { "instructions": str, "model": "exa-research" (opcionális) }
    """
    instructions = (body.get("instructions") or "").strip()
    if not instructions:
        raise HTTPException(status_code=400, detail="Hiányzó 'instructions'.")

    url = ""
    headers = {
        "Content-Type": "application/json",
        "x-api-key": EXA_API_KEY,
    }
    payload = {
        "model": body.get("model", "exa-research"),
        "instructions": instructions,
    }
    r = requests.post(url, headers=headers, json=payload, timeout=60)
    if r.status_code not in (200, 201):
        raise HTTPException(status_code=502, detail=f"Exa research error: {r.text}")
    return r.json()


@app.post("/api/chat")
async def api_chat(request: Request):
    """
    Streaming chat a Cerebras gpt-oss-120b-vel (fix 20k max_completion_tokens, fix temperature és top_p).
    Input JSON:
    {
      "user": "felhasználói üzenet",
      "deep_context": "opcionális kontextus a webből (Exa)"
    }
    Válasz: text/event-stream (SSE), tokenenkénti darabolással.
    """
    body = await request.json()
    user_text: str = (body.get("user") or "").strip()
    deep_context: Optional[str] = (body.get("deep_context") or "").strip()

    if not user_text:
        raise HTTPException(status_code=400, detail="Hiányzó 'user' üzenet.")

    # Ragaszkodunk a fix rendszerprompt-struktúrához (string content)
    system_content = ""
    if deep_context:
        system_content = (
            "Külső, valós webes forrásokból gyűjtött kontextus az alábbiakban. "
            "Mindig hivatkozz a kontextus tartalmára következetesen a válaszban, és jelezd, ha valami hiányos.\n\n"
            + deep_context
        )

    def sse_event_generator():
        try:
            stream = client.chat.completions.create(
                messages=[
                    {"role": "system", "content": system_content},
                    {"role": "user", "content": user_text},
                ],
                model="gpt-oss-120b",
                stream=True,
                max_completion_tokens=20000,
                temperature=0.03,
                top_p=0.08,
            )
            for chunk in stream:
                delta = getattr(chunk.choices[0].delta, "content", None)
                if delta:
                    yield f"data: {delta}\n\n"
            # jelzés a stream végére
            yield "event: done\ndata: [DONE]\n\n"
        except Exception as e:
            err = str(e).replace("\n", " ")
            yield f"event: error\ndata: {err}\n\n"

    return StreamingResponse(sse_event_generator(), media_type="text/event-stream")


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    uvicorn.run("main:app", host="0.0.0.0", port=port, reload=False)
