.interface-header h2 { display: flex; align-items: center; justify-content: center; gap: 10px; margin-bottom: 8px; font-size: 1.4rem; }
.interface-header p { color: var(--text-muted); font-size: 0.95rem; line-height: 1.4; }
.interface-content { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; }
.input-section { margin-bottom: 25px; }
.input-section h3 { margin-bottom: 15px; color: var(--text); font-size: 1.1rem; }
.input-section textarea, .input-section input, .input-section select { width: 100%; background: var(--glass-strong); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; color: var(--text); font-size: 0.9rem; font-family: inherit; transition: border-color 0.2s ease; }
.input-section textarea:focus, .input-section input:focus, .input-section select:focus { outline: none; border-color: var(--primary); }
.input-section textarea { resize: vertical; min-height: 120px; font-family: 'SF Mono', monospace; }
.options-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-top: 20px; }
.input-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
.option-group { display: flex; flex-direction: column; gap: 6px; }
.option-group label { font-size: 0.8rem; font-weight: 600; color: var(--text); }
.action-buttons { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }
.primary-btn, .secondary-btn, .action-btn, .button-primary { padding: 10px 16px; border-radius: var(--radius-md); border: 1px solid var(--border); font-weight: 600; font-size: 0.85rem; cursor: pointer; transition: all 0.2s var(--transition-curve); display: inline-flex; align-items: center; gap: 8px; min-height: 42px; }
.primary-btn, .button-primary { background: linear-gradient(135deg, var(--primary), var(--secondary)); color: white; border-color: var(--primary); }
